using System.Text.Json;
using TheOverseer.App.Monitoring;
using TheOverseer.Core.Models;
using TheOverseer.Tests.Support;

namespace TheOverseer.Tests;

/// <summary>
/// End-to-end bridge tests driven by output the REAL producer modules wrote:
/// <c>integrations/deepseek-harness/fixtures/spool/*</c> is regenerated by
/// <c>fixtures/generate-spool-fixtures.mjs</c>, which runs the shipped observer
/// state machine and the shipped spool writer (atomic current.json, rotation,
/// bounded queue with drop accounting). Nothing here is a hand-written document,
/// so a change in the producer's actual shape fails these tests.
/// </summary>
public sealed class BridgeProducerFixtureTests
{
    /// <summary>The deterministic clock the fixture generator used.</summary>
    private static readonly DateTimeOffset ProducerStart = new(2026, 1, 1, 0, 0, 0, TimeSpan.Zero);
    private static readonly SourceInstance DshFixture = new(HarnessIds.Dsh, "dsh-fixture", "DeepSeek Harness");

    [Theory]
    [InlineData("question-pending", AgentTaskState.NeedsInput, true)]
    [InlineData("question-unavailable", AgentTaskState.NeedsInput, false)]
    [InlineData("question-answered", AgentTaskState.Idle, true)]
    public async Task QuestionProducerCurrentStateRestoresAttentionThroughTheRealAdapter(string name, AgentTaskState expected, bool complete)
    {
        using var fixture = BridgeFixture.Create(name);
        var clock = new ManualTimeProvider(ProducerStart);
        await using var adapter = fixture.CreateAdapter(clock);
        await adapter.StartAsync(new CancellationToken(canceled: true));
        var snapshot = adapter.Poll();
        Assert.Equal(expected, Assert.Single(snapshot.Tasks).State);
        Assert.Equal(complete, snapshot.CoverageComplete);
        var task = Assert.Single(snapshot.Tasks);
        Assert.Equal(!complete, task.IsStateUncertain);
        var vm = new TheOverseer.UI.ViewModels.HudViewModel(TheOverseer.Core.Configuration.HudSettings.Default);
        vm.ApplySnapshot(TheOverseer.Core.Models.MonitoringSnapshot.Empty(ProducerStart) with
        {
            Tasks = snapshot.Tasks,
        });
        if (!complete)
            Assert.Contains("Input status unconfirmed", Assert.Single(vm.Tasks).RowSubtitle);
        Assert.Empty(snapshot.Transitions); // Restart hydration must stay quiet.
        Assert.Equal(CapabilitySupport.Supported, snapshot.Capabilities.InputRequests.Support);
        Assert.DoesNotContain("SECRET_", snapshot.ToString() + string.Join("\n", snapshot.Tasks), StringComparison.Ordinal);
    }

    [Fact]
    public async Task LiveProducerFixtureIsConsumedWithAuthoritativeCoverage()
    {
        using var fixture = BridgeFixture.Create("live");
        var clock = new ManualTimeProvider(ProducerStart);
        await using var adapter = fixture.CreateAdapter(clock);
        await adapter.StartAsync(new CancellationToken(canceled: true));

        var snapshot = adapter.Poll();

        Assert.True(snapshot.CoverageComplete, string.Join(",", snapshot.HealthReasons));
        Assert.Equal(MonitoringHealthLevel.Healthy, snapshot.Health);
        var expected = fixture.ExpectedSessions();
        Assert.Equal(expected.Count, snapshot.Tasks.Count);
        foreach (var sessionId in expected)
        {
            Assert.Contains(snapshot.Tasks, task => task.ConversationId == sessionId);
        }

        // The producer's own current-state document is what proves completeness.
        Assert.Contains("resyncs=", adapter.Describe(), StringComparison.Ordinal);
        Assert.DoesNotContain("gaps=1", adapter.Describe(), StringComparison.Ordinal);

        // Privacy: the fixture catalog carries SECRET_* canaries that must never
        // survive into a normalized task.
        var rendered = string.Join("\n", snapshot.Tasks.Select(task => task.ToString()));
        Assert.DoesNotContain("SECRET_", rendered, StringComparison.Ordinal);
    }

    [Fact]
    public async Task DroppedRecordsStayHonestThenRecoverFromTheProducersCurrentState()
    {
        using var fixture = BridgeFixture.Create("dropped");
        var clock = new ManualTimeProvider(ProducerStart);
        var currentPath = Path.Combine(fixture.SpoolDirectory, "current.json");
        var authoritative = File.ReadAllBytes(currentPath);
        File.Delete(currentPath);
        await using var adapter = fixture.CreateAdapter(clock);
        await adapter.StartAsync(new CancellationToken(canceled: true));

        // Without the producer's document, records the bounded queue dropped leave
        // an honest hole: some sessions were never observed.
        var degraded = adapter.Poll();
        Assert.False(degraded.CoverageComplete);
        Assert.Contains(degraded.HealthReasons, reason => reason.Contains("bridge-", StringComparison.Ordinal));
        Assert.True(adapter.Describe().Contains("producer-dropped:6", StringComparison.Ordinal), adapter.Describe());

        // The producer publishes its current state after folding the dropped records,
        // so current coverage recovers from the authoritative document...
        clock.AdvanceSeconds(1);
        File.WriteAllBytes(currentPath, authoritative);
        var recovered = adapter.Poll();

        Assert.True(recovered.CoverageComplete, string.Join(",", recovered.HealthReasons));
        var expected = fixture.ExpectedSessions();
        Assert.Equal(expected.Count, recovered.Tasks.Count);
        foreach (var sessionId in expected)
        {
            Assert.Contains(recovered.Tasks, task => task.ConversationId == sessionId);
        }

        // ...while the history hole stays visible: lost records are never rewritten
        // as observed activity, even though current state is now complete.
        Assert.Contains(recovered.HealthReasons, reason => reason == "bridge-history-gap");
    }

    [Fact]
    public async Task RotationDuringConsumptionDoesNotLoseTheUnreadTail()
    {
        using var fixture = BridgeFixture.Create("live");
        var spool = fixture.SpoolDirectory;
        var clock = new ManualTimeProvider(ProducerStart);
        // Rotation is a real producer behaviour; the test reproduces the producer's
        // exact file operations (rename, then keep appending to a new file) with the
        // producer's own bytes.
        var stream = File.ReadAllBytes(Path.Combine(spool, "events.jsonl"));
        var split = SplitAtLineBoundary(stream, stream.Length * 6 / 10);
        var currentPath = Path.Combine(spool, "current.json");
        var authoritative = File.ReadAllBytes(currentPath);
        foreach (var name in new[] { "current.json", "health.json" })
        {
            File.Delete(Path.Combine(spool, name));
        }

        File.WriteAllBytes(Path.Combine(spool, "events.jsonl"), stream[..split]);
        await using var adapter = fixture.CreateAdapter(clock);
        await adapter.StartAsync(new CancellationToken(canceled: true));
        adapter.Poll();

        // The producer rotates: rename the live file, then keep appending to a new one.
        File.Move(Path.Combine(spool, "events.jsonl"), Path.Combine(spool, "events-20260101T000100Z.jsonl"));
        File.WriteAllBytes(Path.Combine(spool, "events.jsonl"), stream[split..]);
        clock.AdvanceSeconds(1);
        var snapshot = adapter.Poll();

        var expectedRecords = CountRecords(stream);
        Assert.Contains("applied=" + expectedRecords.ToString(System.Globalization.CultureInfo.InvariantCulture), adapter.Describe(), StringComparison.Ordinal);
        Assert.Contains("gaps=0", adapter.Describe(), StringComparison.Ordinal);
        Assert.DoesNotContain("bridge-rotated-unread", snapshot.HealthReasons);
        Assert.Equal(2, snapshot.Tasks.Count);

        // The authoritative document then proves the current state, so the source is
        // not left permanently degraded by a rotation that lost nothing.
        clock.AdvanceSeconds(1);
        File.WriteAllBytes(currentPath, authoritative);
        var synced = adapter.Poll();
        Assert.True(synced.CoverageComplete, string.Join(",", synced.HealthReasons));
    }

    [Fact]
    public async Task RotatedProducerFixtureIsConsumedThroughItsAuthoritativeSnapshot()
    {
        using var fixture = BridgeFixture.Create("rotated");
        var clock = new ManualTimeProvider(ProducerStart);
        // The fixture already contains the producer's rotated files; consuming the
        // live tail must not be confused by their presence.
        Assert.NotEmpty(Directory.GetFiles(fixture.SpoolDirectory, "events-*.jsonl"));
        await using var adapter = fixture.CreateAdapter(clock);
        await adapter.StartAsync(new CancellationToken(canceled: true));

        var snapshot = adapter.Poll();

        Assert.True(snapshot.CoverageComplete, string.Join(",", snapshot.HealthReasons));
        Assert.Equal(fixture.ExpectedSessions().Count, snapshot.Tasks.Count);
        Assert.DoesNotContain("bridge-rotated-unread", snapshot.HealthReasons);
    }

    [Fact]
    public async Task RepeatedPollingOfAnUnchangedSourceDoesNotResurrectAttention()
    {
        using var fixture = BridgeFixture.Create("live");
        var clock = new ManualTimeProvider(ProducerStart);
        await using var adapter = fixture.CreateAdapter(clock);
        var received = new List<AttentionEvent>();
        adapter.SnapshotAvailable += snapshot => received.AddRange(snapshot.Transitions);
        await adapter.StartAsync(new CancellationToken(canceled: true));

        adapter.Poll();
        clock.AdvanceSeconds(2);
        adapter.Poll();
        clock.AdvanceSeconds(2);
        adapter.Poll();

        // Retained backlog is hydration: attaching to a producer that already has
        // history must never replay its old attention as new notifications.
        Assert.Empty(received);
    }

    [Fact]
    public async Task BridgeFreshnessComesFromTheProducerNotFromThePoll()
    {
        using var fixture = BridgeFixture.Create("live");
        var clock = new ManualTimeProvider(ProducerStart);
        await using var adapter = fixture.CreateAdapter(clock);
        await adapter.StartAsync(new CancellationToken(canceled: true));

        var first = adapter.Poll();
        Assert.NotEqual(default, first.EffectiveEvidenceAt);
        Assert.True(first.EffectiveEvidenceAt <= clock.GetUtcNow());

        // An hour of polling an idle spool must not look like an hour of fresh reads:
        // evidence stays the producer's own observation time, bounded by the receipt
        // clock, and never advances to "now".
        clock.AdvanceSeconds(3600);
        var second = adapter.Poll();

        Assert.True(second.EffectiveEvidenceAt < second.ObservedAt);
        Assert.True(second.EffectiveEvidenceAt <= ProducerStart.AddSeconds(10), "evidence must stay the producer's time");
        Assert.Equal(clock.GetUtcNow(), second.ObservedAt);
    }

    [Fact]
    public async Task ASharedBudgetBoundsHowMuchOneSourceReadsPerPass()
    {
        var root = Path.Combine(Path.GetTempPath(), "overseer-tests", Guid.NewGuid().ToString("N"));
        var source = new SourceInstance(HarnessIds.Dsh, "dsh-budget", "DeepSeek Harness");
        var clock = new ManualTimeProvider(ProducerStart);
        await using var adapter = new BridgeMonitorAdapter(source, root, timeProvider: clock, actionLease: TimeSpan.FromHours(1));
        Directory.CreateDirectory(adapter.SpoolDirectory);
        try
        {
            var padding = new string('p', 500);
            var lines = new List<string>();
            for (var sequence = 0; sequence < 200; sequence++)
            {
                lines.Add("{\"schemaVersion\":1,\"harnessId\":\"dsh\",\"sourceInstanceId\":\"dsh-budget\"," +
                          "\"sourceEpoch\":\"epoch\",\"sessionId\":\"session-budget\",\"sequence\":" + sequence + "," +
                          "\"eventId\":\"e" + sequence + "\",\"observedAtUtc\":\"" + ProducerStart.ToString("o") + "\"," +
                          "\"kind\":\"tool/start\",\"turnId\":\"turn-1\",\"projectRoot\":\"" + padding + "\"," +
                          "\"category\":\"working\",\"evidence\":\"explicit\",\"hydration\":false,\"producerVersion\":\"test\"}");
            }

            File.WriteAllLines(Path.Combine(adapter.SpoolDirectory, "events.jsonl"), lines);
            adapter.ApplyBudget(new SourceBudget(SourceBudget.MinimumBytesPerPass, 64, "test-share"));
            await adapter.StartAsync(new CancellationToken(canceled: true));

            adapter.Poll();
            var appliedInOnePass = Applied(adapter.Describe());
            Assert.True(appliedInOnePass < lines.Count, "one pass must not read the whole spool: " + adapter.Describe());

            for (var pass = 0; pass < 24 && Applied(adapter.Describe()) < lines.Count; pass++)
            {
                adapter.Poll();
            }

            // Bounded per pass, but it still completes: a share is a rate, not a cap
            // on what the source can ever observe.
            Assert.Equal(lines.Count, Applied(adapter.Describe()));
        }
        finally
        {
            Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task AnOldHistoryGapStopsDegradingTheSourceWhileCurrentStateStaysComplete()
    {
        using var fixture = BridgeFixture.Create("dropped");
        var clock = new ManualTimeProvider(ProducerStart);
        await using var adapter = fixture.CreateAdapter(clock, staleLease: TimeSpan.FromHours(4));
        await adapter.StartAsync(new CancellationToken(canceled: true));

        // The pass that notices the drop reports it honestly ...
        var notice = adapter.Poll();
        Assert.False(notice.CoverageComplete);
        Assert.Contains(notice.HealthReasons, reason => reason.Contains("bridge-coverage-incomplete", StringComparison.Ordinal));

        // ... and the next authoritative document clears current state, while the
        // history hole stays visible for as long as it can affect the strip.
        var gapInWindow = adapter.Poll();
        Assert.True(gapInWindow.CoverageComplete, string.Join(",", gapInWindow.HealthReasons));
        Assert.Contains("bridge-history-gap", gapInWindow.HealthReasons);
        Assert.Equal(MonitoringHealthLevel.Degraded, gapInWindow.Health);

        // The hole is real, but once it is older than the activity window it can no
        // longer affect anything the HUD shows, so it stops degrading the source.
        clock.AdvanceSeconds(2 * 60 * 60);
        var later = adapter.Poll();
        Assert.True(later.CoverageComplete, string.Join(",", later.HealthReasons));

        Assert.True(later.CoverageComplete, string.Join(",", later.HealthReasons));
        Assert.DoesNotContain("bridge-history-gap", later.HealthReasons);
        Assert.Equal(MonitoringHealthLevel.Healthy, later.Health);
        Assert.DoesNotContain("producer-dropped", adapter.Describe());
    }

    [Fact]
    public async Task BridgeCapabilitiesDescribeWhatTheBridgeActuallyProvides()
    {
        using var fixture = BridgeFixture.Create("live");
        var clock = new ManualTimeProvider(ProducerStart);
        await using var adapter = fixture.CreateAdapter(clock);
        await adapter.StartAsync(new CancellationToken(canceled: true));

        var capabilities = adapter.Poll().Capabilities;

        // The bridge exports correlated requests and explicit outcomes, so it must
        // not inherit the Codex capability set that calls those unsupported.
        Assert.Equal(CapabilitySupport.Supported, capabilities.PermissionRequests.Support);
        Assert.Equal(CapabilitySupport.Unsupported, capabilities.InputRequests.Support);
        Assert.Equal("dsh-input-events-unavailable", capabilities.InputRequests.Code);
        Assert.Contains("not emitted", capabilities.InputRequests.Note, StringComparison.Ordinal);
        Assert.Equal(CapabilitySupport.Supported, MonitorCapabilities.ForBridge(HarnessIds.Claude, continuousHeartbeat: false).InputRequests.Support);
        Assert.Equal(CapabilitySupport.Supported, capabilities.TaskFailureEvidence.Support);
        Assert.Equal(CapabilitySupport.Unsupported, MonitorCapabilities.Initial.PermissionRequests.Support);
        // What it genuinely cannot provide stays unsupported and says why.
        Assert.Equal(CapabilitySupport.Unsupported, capabilities.SessionTitles.Support);
        Assert.Equal(CapabilitySupport.Unsupported, capabilities.RuntimeActivitySource.Support);
        Assert.Contains("DeepSeek Harness", capabilities.PermissionRequests.Note, StringComparison.Ordinal);

        // A one-shot hook source is event-driven: its capability note must say that
        // absence proves neither idle nor disconnection.
        Assert.Contains("absence of events", MonitorCapabilities.ForBridge(HarnessIds.Claude, continuousHeartbeat: false).AttentionLiveVerification.Note, StringComparison.Ordinal);
        Assert.Contains("heartbeat", MonitorCapabilities.ForBridge(HarnessIds.Dsh, continuousHeartbeat: true).AttentionLiveVerification.Note, StringComparison.Ordinal);
    }

    private static long Applied(string description)
    {
        foreach (var part in description.Split(' '))
        {
            if (part.StartsWith("applied=", StringComparison.Ordinal) &&
                long.TryParse(part[8..], System.Globalization.CultureInfo.InvariantCulture, out var value))
            {
                return value;
            }
        }

        throw new InvalidOperationException("no applied counter in " + description);
    }

    private static int SplitAtLineBoundary(byte[] stream, int target)
    {
        var index = Math.Clamp(target, 1, stream.Length - 1);
        while (index > 0 && stream[index - 1] != (byte)'\n')
        {
            index--;
        }

        Assert.True(index > 0, "fixture stream has no complete line before the split");
        return index;
    }

    private static int CountRecords(byte[] stream) =>
        stream.Count(value => value == (byte)'\n');

    /// <summary>Isolated copy of one generated producer spool.</summary>
    private sealed class BridgeFixture : IDisposable
    {
        private readonly string _root;
        private readonly string _name;

        private BridgeFixture(string name)
        {
            _name = name;
            _root = Path.Combine(Path.GetTempPath(), "overseer-tests", Guid.NewGuid().ToString("N"));
            SpoolDirectory = Path.Combine(_root, "bridges", "dsh", "dsh-fixture");
            Directory.CreateDirectory(SpoolDirectory);
            foreach (var source in Directory.GetFiles(FixtureDirectory(name)))
            {
                File.Copy(source, Path.Combine(SpoolDirectory, Path.GetFileName(source)));
            }
        }

        public string SpoolDirectory { get; }

        public static BridgeFixture Create(string name) => new(name);

        public BridgeMonitorAdapter CreateAdapter(TimeProvider clock, TimeSpan? staleLease = null) =>
            new(DshFixture, _root, timeProvider: clock, staleLease: staleLease);

        public IReadOnlyList<string> ExpectedSessions()
        {
            using var document = JsonDocument.Parse(File.ReadAllText(Path.Combine(FixtureRoot(_name), "expected.json")));
            return document.RootElement.GetProperty("sessions").EnumerateArray().Select(item => item.GetString()!).ToArray();
        }

        private static string FixtureRoot(string name) =>
            Path.Combine(RepositoryRoot(), "integrations", "deepseek-harness", "fixtures", "spool", name);

        private static string FixtureDirectory(string name) =>
            Path.Combine(FixtureRoot(name), "root", "dsh", "dsh-fixture");

        private static string RepositoryRoot()
        {
            for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
            {
                if (File.Exists(Path.Combine(directory.FullName, "TheOverseer.sln")))
                {
                    return directory.FullName;
                }
            }

            throw new InvalidOperationException("repository root not found from " + AppContext.BaseDirectory);
        }

        public void Dispose()
        {
            try
            {
                Directory.Delete(_root, recursive: true);
            }
            catch (IOException)
            {
            }
            catch (UnauthorizedAccessException)
            {
            }
        }
    }
}
